"""Valid: the data files are regenerated by a child process between the arms, but byte-identically."""
import hashlib
import subprocess
import sys
from pathlib import Path

LOOP = "train"
KIND = "valid"
FAULT_CLASS = "none (data rewritten between arms, deterministically identical)"
DESCRIPTION = (
    "Before the treatment run the experimenter, unsure whether the data on this box was current, re-ran "
    "`python make_data.py`, which rewrites data/train.csv, val.csv and test.csv (new mtimes, test split "
    "included). The generator is seeded per split, so the rewritten files are byte-identical to the ones "
    "the baseline used; the only difference between the arms is TRAINER_FEATURES=quad."
)
TREATMENT = ["env:TRAINER_FEATURES"]
REPLICATES = 3
CLAIM_METRIC = "val_acc"


def regenerate_data(root, arm):
    root = Path(root)
    splits = ("train", "val", "test")
    before = {s: hashlib.sha256((root / "data" / f"{s}.csv").read_bytes()).hexdigest() for s in splits}
    subprocess.run([sys.executable, "make_data.py"], cwd=root, check=True, capture_output=True)
    after = {s: hashlib.sha256((root / "data" / f"{s}.csv").read_bytes()).hexdigest() for s in splits}
    # The experimenter's own sanity check after regenerating (it holds: the generator is seeded).
    assert before == after, "regenerated data differs from the committed data"


ARMS = {
    "A": dict(cmd=["train.py", "--seed", "{seed}", "--out", "out/{arm}{seed}"], role="train"),
    "B": dict(cmd=["train.py", "--seed", "{seed}", "--out", "out/{arm}{seed}"], role="train",
              env={"TRAINER_FEATURES": "quad"}, before=regenerate_data),
}
